-- producer_countries|germany|notes|zh — 本德 en latin
UPDATE `producer_countries` SET `notes_zh` = '德国在十九世纪曾是雪茄中心——不来梅、Bünde、巴伐利亚——如今留下的是机制工业。手工卷制在此由个人重振：一位在古巴受训的科隆女子、一位定居德累斯顿的古巴卷工、一个从未停手的巴伐利亚家族。本图集在此开辟的不是种植之国，而是卷制之地，一如巴哈马。'
 WHERE `id` = 'germany' AND SHA1(TRIM(`notes`)) = '9ddcac755882ac3141f550572c2a719d564a9d97';
