-- producer_countries|russia|notes|zh — marque Pogar en latin
UPDATE `producer_countries` SET `notes_zh` = '两家工厂，两个时代：布良斯克州的 Pogar 自1915年起在一处1839年的旧址卷制，靠廉价产品熬过革命与战争后重返雪茄；莫斯科的 Siglo de Oro 2011年诞生于一位建筑企业家的热情，卷工来自古巴和尼加拉瓜。本图集把俄罗斯列为卷制之地，不设产区与品种：烟叶来自别处。'
 WHERE `id` = 'russia' AND SHA1(TRIM(`notes`)) = 'bf5228cb74f6b8f61740dbe35ad9312a41acad67';
