UPDATE `habanos_presence` SET `description_zh` = '尼加拉瓜按产量计已超过古巴与多米尼加共和国，成为全球优质雪茄产量领先的产地。产业集中于“雪茄之都”埃斯特利，各大名厂在此设厂。与古巴不同，尼加拉瓜产业完全私营，竞争激烈。'
